body:has(.hatcher-source) > #header,
body:has(.hatcher-source) > #footer { display: none; }
.hatcher-source {
  --font-inter: "__Inter_8b3a0b", Arial;
  --font-sora: "__Sora_1a977f", Arial;
  --font-noto-tc: "__Noto_Sans_TC_45950f", "Microsoft JhengHei";
  --background: #fff;
  --foreground: #0f172a;
  font: 16px/1.65 "__Inter_8b3a0b","__Noto_Sans_TC_45950f",system-ui,sans-serif;
  color: #0f172a;
  text-wrap: wrap;
}
.hatcher-source [hidden] { display: none !important; }
.hatcher-source [data-highlight-toggle][aria-expanded="true"] svg { transform: rotate(180deg); }
.hatcher-source.hatcher-scrolled header { padding-block: .75rem; }
.hatcher-source.hatcher-scrolled header > div:first-child > div:first-child { box-shadow: 0 10px 26px rgba(15,23,42,.08); }
.hatcher-source .hatcher-mobile-panel {
  position: fixed;
  inset: 70px 0 0;
  overflow: auto;
  background: white;
  padding-top: 12px;
}
.hatcher-source:has([data-hatcher-mobile-toggle][aria-expanded="true"]) header { background: white; }
.hatcher-source [data-hatcher-mobile-toggle][aria-expanded="true"] svg { display: none; }
.hatcher-source [data-hatcher-mobile-toggle][aria-expanded="true"]::before { content: "×"; font-size: 22px; font-weight: 300; }
.hatcher-source .hatcher-mobile-item {
  display: block;
  border-radius: 12px;
  padding: 10px 14px;
  color: #334155;
  font-size: .95rem;
  font-weight: 500;
}
.hatcher-source .hatcher-mobile-item:hover { background: #f1f5f9; }
.hatcher-source [id]:not([aria-hidden]) { scroll-margin-top: 90px; }
@media (min-width:1280px) {
  .hatcher-source .hatcher-mobile-panel { display: none; }
}

